.yb-ai-btn {
  display: inline-block; padding: 12px 28px; border-radius: 10px;
  font-size: 16px; text-decoration: none; transition: transform .15s ease, box-shadow .15s ease;
}
.yb-ai-btn:hover { transform: translateY(-2px); }
.yb-ai-btn--primary { background: #fff; color: #1446e6; font-weight: 600; box-shadow: 0 8px 20px rgba(0,0,0,.15); }
.yb-ai-btn--ghost { border: 1px solid rgba(255,255,255,.7); color: #fff; }

/* Features */
.yb-ai-features { max-width: 1080px; margin: 0 auto; padding: 72px 24px 96px; }
.yb-ai-features-title { margin: 0 0 40px; text-align: center; font-size: 32px; color: #1f2933; }
.yb-ai-features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.yb-ai-card {
  background: #fff;
  border: 1px solid #e3e8ef;
  border-radius: 16px;
  padding: 32px 28px;
  box-shadow: 0 4px 16px rgba(31,41,51,.06);
  transition: transform .2s ease, box-shadow .2s ease;
}
.yb-ai-card:hover { transform: translateY(-4px); box-shadow: 0 12px 28px rgba(20,70,230,.12); }
.yb-ai-card-icon {
  width: 52px; height: 52px; display: flex; align-items: center; justify-content: center;
  font-size: 26px; border-radius: 12px; background: #eaf0ff; margin-bottom: 18px;
}
.yb-ai-card-title { margin: 0 0 10px; font-size: 20px; color: #1f2933; }
.yb-ai-card-text { margin: 0; font-size: 15px; color: #5a6a7e; }

/* Footer */
.yb-ai-footer {
  padding: 28px 24px;
  text-align: center;
  background: #101828;
  color: #98a2b3;
}
.yb-ai-footer-text { margin: 0; font-size: 14px; }

