@media (max-width: 768px) {
  .yb-ai-header { padding: 12px 16px; }
  .yb-ai-nav { gap: 12px; }
  .yb-ai-hero-title { font-size: 36px; }
  .yb-ai-hero { padding: 72px 16px 64px; }
  .yb-ai-features-grid { grid-template-columns: 1fr; }
  .yb-ai-features { padding: 56px 16px 72px; }
}
